<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main">
            <van-form @submit="onSubmit">
                <div class="formCol">
                    <div class="item">
                        <div class="label">子账户用户名</div>
                        <div class="item-rt">
                            <input @change="selects()"  minlength="4" v-model="ruleForm.account" :rules="rules.account" class="addInput" /><span v-if="users" style="color: blue;margin-top: 5px;margin-left:3px;">账户可用</span>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">子账号昵称</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.nickName" :rules="rules.nickName" class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">状态</div>
                        <div class="item-rt">
                            <van-radio-group v-model="ruleForm.status" direction="horizontal">
                                <van-radio :name="1">启用</van-radio>
                                <van-radio :name="2">禁用</van-radio>
                                <van-radio :name="3">冻结</van-radio>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">登录密码</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.passwd" :rules="rules.passwd"  class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">IP绑定</div>
                        <div class="item-rt">
                          <input  v-model="ruleForm.whiteIp"  class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">菜单显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox" direction="horizontal" v-model="ruleForm.ridios">
                                <template v-for="(item, index) in proxySubLimit" :key="index + 1">
                                    <van-checkbox v-show="item.show" style="margin-bottom:5px;width:110px;height:20px;" :name="item.id"  shape="square">{{ item.name }}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                    <div class="fobtn">
                        <div @click="cancelForm" class="fobcanl">取消</div>
                        <div @click="onSubmit" class="fobmits">确定</div>
                    </div>
                </div>
            </van-form>
        </div>
    </div>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();


// 加载状态
const loading = ref(false)

// 菜单列表
const proxySubLimit = ref([
    { name: '即时注单', id: 4, show: false },
    { name: '数据分析', id: 5, show: false },
    { name: '用户管理', id: 6, show: false },
    { name: '赔率设置', id: 7, show: false },
    { name: '个人资料', id: 8, show: false },
    { name: '报表查询', id: 9, show: false },
    { name: '开奖记录', id: 10, show: false },
    { name: '手动降倍', id: 15, show: false },
    { name: '货量降倍', id: 11, show: false },
    { name: '会员降倍', id: 12, show: false },
    { name: '自动降倍', id: 13, show: false },
])

// 表单数据
const ruleForm = reactive({
    account: '',
    nickName: '',
    status: 1,
    passwd: '',
    whiteIp: '',
    menuList: [],
    lotteryList: [],
    ridios: [],
    password: '',
    role: 4
})
const users = ref(false)
const num = ref(3)
const tits = ref('子账号新增')
const selects = async () => {
    const reg = /^[a-zA-Z]\w{3,9}$/
    if (!ruleForm.account) return
    if (!reg.test(ruleForm.account)) {
        showToast({
            message: '请输入正确账号首个字母为英文加数字组合，4-10位数!',
            icon: 'fail',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        ruleForm.account = ""
        return false
    }
    let username = ruleForm.account.toLowerCase()
    try {
        const data = await userStore.checkAcc(username)
        if (data.data) {
            users.value = true
            return true
        } else {
            users.value = false
            ruleForm.account = ""
            showToast({
                message: '账号已存在!',
                icon: 'fail',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return false
        }
    } catch (error) {
        console.error(error)
    }
}
// 表单验证规则
const rules = reactive({
    account: [
        { required: true, message: '请填写账户', trigger: 'blur' },
        { type: 'string', pattern: /^[\w\d-]{4,}$/, message: '账号使用英文字符、数字4位以上', trigger: 'blur' },
        { min: 4, message: '账户最小4个字符', trigger: 'blur' },
    ],
    passwd: [
        { required: true, message: '请填写登录密码', trigger: 'blur' },
        {
            type: 'string',
            pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
            message: '密码由6位以上英文、数字、特殊符号组成',
            trigger: 'blur'
        },
    ],
})

// 获取子账号菜单权限
const getProxySubLimit = async () => {
    try {
        const res = await userStore.getMenu()
        if (res.data && res.data.length > 0) {
            proxySubLimit.value.forEach(its => {
                res.data.forEach(item => {
                    if (item == its.id) {
                        its.show = true
                    }
                })
            })
        }
    } catch (error) {
        console.log('getProxySubLimit error:', error)
    }
}

// 提交表单
const onSubmit = async () => {
    try {
        // 设置菜单列表
        ruleForm.menuList = [...ruleForm.ridios]
        
        // 加密密码
        if (ruleForm.passwd) {
            let paw = ruleForm.passwd.toLowerCase()
            ruleForm.password = md5(paw)
        }
        
        ruleForm.role = 4
        
        await addsubaccount(ruleForm)
    } catch (error) {
        console.error('onSubmit error:', error)
    }
}

// 添加子账号
const addsubaccount = async (data) => {
    try {
        loading.value = true
        const res = await userStore.subAdd(data)
        showToast({
            message: '新增成功',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        if (res.code == 200) {
            loading.value = false
            router.push({ path: '/subaccount' })
        } else {
            loading.value = false
        }
    } catch (error) {
        loading.value = false
        console.error('addsubaccount error:', error)
        showToast({ type: 'error', message: '添加子账号失败' })
    }
}

// 取消表单
const cancelForm = () => {
    router.push({ path: '/subaccount' })
}

// 生命周期
onMounted(() => {
    getProxySubLimit()
})
</script>

<style scoped>
.page {
    height: 100vh;
    background-color: var(--blue-surface-b-50);
}
</style>